-- Speak: a build-up course in the Michel Thomas manner — sessions, their steps,
-- and where each learner has got to.
--
-- Generated by drizzle-kit, then made idempotent by hand. Purely additive — three
-- new tables. Nothing is dropped and no existing row is touched, so this is safe
-- on a live database.

CREATE TABLE IF NOT EXISTS "speak_progress" (
	"user_id" text NOT NULL,
	"session_id" text NOT NULL,
	"completed_at" timestamp DEFAULT now() NOT NULL,
	"got_it" integer NOT NULL,
	"total" integer NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "speak_progress_user_id_session_id_pk" PRIMARY KEY("user_id","session_id")
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "speak_sessions" (
	"id" text PRIMARY KEY NOT NULL,
	"language_id" text NOT NULL,
	"level_id" text NOT NULL,
	"code" text NOT NULL,
	"number" integer NOT NULL,
	"title" text NOT NULL,
	"title_en" text NOT NULL,
	"published" boolean DEFAULT false NOT NULL,
	"source_id" text,
	"source_ref" text,
	"source_hash" text,
	"human_edited" boolean DEFAULT false NOT NULL,
	"locked_fields" text[] DEFAULT '{}' NOT NULL,
	"upstream_removed_at" timestamp,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "speak_steps" (
	"id" text PRIMARY KEY NOT NULL,
	"session_id" text NOT NULL,
	"index" integer NOT NULL,
	"kind" text NOT NULL,
	"en" text NOT NULL,
	"text" text,
	"reading_kana" text,
	"note" text,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "speak_steps_answer_matches_kind" CHECK (("speak_steps"."kind" = 'prompt' and "speak_steps"."text" is not null and "speak_steps"."reading_kana" is not null)
      or ("speak_steps"."kind" = 'explain' and "speak_steps"."text" is null and "speak_steps"."reading_kana" is null))
);
--> statement-breakpoint
